impl std::hash::Hash for HarnessRunRef {
    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
        std::hash::Hash::hash(&self.run_id, state);
        std::hash::Hash::hash(&self.run_revision.get(), state);
    }
}

